#!/usr/bin/env python3
"""Extract BTC timestamps and prices from a Chroma JSON export."""

from __future__ import annotations

import csv
import json
import re
import sys
from pathlib import Path
from typing import Any, Iterable, Iterator


# Edit these values if the input or output location changes.
INPUT_JSON_PATH = Path(
    "/Users/guttikonda/Desktop/training docs/chroma_db_reader/chroma-export.json"
)
OUTPUT_CSV_PATH = Path(
    "/Users/guttikonda/Desktop/training docs/json_reader/output/btc_prices.csv"
)

PRICE_PATTERN = re.compile(
    r"\bprice\s+of\s+\$([0-9]+(?:\.[0-9]+)?)",
    re.IGNORECASE,
)


def extract_btc_rows(records: Iterable[Any]) -> Iterator[tuple[Any, str]]:
    """Yield (metadata timestamp, document price) for every BTC record."""
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError(f"Record {index} is not a JSON object")

        metadata = record.get("metadata")
        if not isinstance(metadata, dict):
            raise ValueError(f"Record {index} has no valid metadata object")

        if str(metadata.get("asset", "")).upper() != "BTC":
            continue

        timestamp = metadata.get("time")
        if timestamp is None:
            raise ValueError(f"BTC record {index} has no metadata.time value")

        document = record.get("document")
        if not isinstance(document, str):
            raise ValueError(f"BTC record {index} has no valid document string")

        price_match = PRICE_PATTERN.search(document)
        if price_match is None:
            raise ValueError(f"Could not find the BTC price in record {index}")

        yield timestamp, price_match.group(1)


def convert_json_to_csv(input_path: Path, output_path: Path) -> int:
    """Convert a JSON array of Chroma records and return the rows written."""
    with input_path.open(encoding="utf-8") as input_file:
        records = json.load(input_file)

    if not isinstance(records, list):
        raise ValueError("The input JSON must contain an array of records")

    rows = list(extract_btc_rows(records))
    output_path.parent.mkdir(parents=True, exist_ok=True)

    with output_path.open("w", encoding="utf-8", newline="") as output_file:
        writer = csv.writer(output_file)
        writer.writerow(("timestamp", "btc_price"))
        writer.writerows(rows)

    return len(rows)


def main() -> int:
    try:
        row_count = convert_json_to_csv(INPUT_JSON_PATH, OUTPUT_CSV_PATH)
    except (OSError, json.JSONDecodeError, ValueError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1

    print(f"Wrote {row_count} BTC rows to {OUTPUT_CSV_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
